import {spawnSync} from 'node:child_process';
try {
const [version,ref,readme,registry,ignoreConflicts]=process.argv.slice(1);
const required=name=>{const value=process.env[name];if(!value?.trim())throw Error('Set '+name+' before publishing');return value;};
const github=required('GH_TOKEN'),requestToken=required('ACTIONS_ID_TOKEN_REQUEST_TOKEN');
const requestUrl=new URL(required('ACTIONS_ID_TOKEN_REQUEST_URL'));
const base=new URL(registry);
if(base.protocol!=='https:'||base.username||base.password||base.search||base.hash||base.pathname!=='/')throw Error('Flakestry URL must be an HTTPS origin');
if(requestUrl.protocol!=='https:')throw Error('OIDC request URL must use HTTPS');
if(!version?.trim()||!ref?.trim())throw Error('version and ref are required');
const evaluate=args=>{const result=spawnSync('nix',['--extra-experimental-features','nix-command flakes','flake',...args,'--no-write-lock-file'],{encoding:'utf8',maxBuffer:64*1024*1024});if(result.error||result.status!==0)throw Error('Nix '+args[0]+' failed; publication cancelled');let value;try{value=JSON.parse(result.stdout);}catch{throw Error('Invalid Nix '+args[0]+' JSON; publication cancelled');}if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Invalid Nix '+args[0]+' result');return {value,errors:result.stderr};};
const metadata=evaluate(['metadata','--json']),outputs=evaluate(['show','--json','--all-systems']);
requestUrl.searchParams.set('audience',base.origin);
const identity=await fetch(requestUrl,{headers:{Authorization:'bearer '+requestToken},redirect:'error',signal:AbortSignal.timeout(120000)});
if(!identity.ok)throw Error('GitHub OIDC request failed: HTTP '+identity.status);
const oidc=(await identity.json()).value;
if(typeof oidc!=='string'||!oidc.trim())throw Error('GitHub OIDC returned no token');
const response=await fetch(new URL('/api/publish',base),{method:'POST',headers:{'Content-Type':'application/json','Github-Token':github,Authorization:'Bearer '+oidc},body:JSON.stringify({metadata:metadata.value,metadata_errors:metadata.errors,outputs:outputs.value,outputs_errors:outputs.errors,readme,version,ref}),redirect:'error',signal:AbortSignal.timeout(120000)});
const conflict=response.status===409&&ignoreConflicts==='true';
if(!response.ok&&!conflict)throw Error('Flakestry publication failed: HTTP '+response.status);
console.log(JSON.stringify({registry:base.origin,version,ref,published:!conflict,alreadyExists:conflict}));
} catch (error) { console.error(error instanceof Error ? error.message : "Nix publishing failed"); process.exitCode=1; }
